"use client";

import Navbar from "@/components/Navbar";
import { useState, useEffect } from "react";

export default function LogsPageClient() {
    const [logs, setLogs] = useState<string[]>([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState("");

    useEffect(() => {
        async function fetchLogs() {
            try {
                const res = await fetch("/api/logs", {
                    cache: "no-store",
                });

                if (!res.ok) {
                    if (res.status === 401) {
                        setError("Unauthorized. Please login as admin.");
                        return;
                    }
                    throw new Error("Failed to fetch logs");
                }

                const data: string[] = await res.json();
                setLogs(data);
            } catch (err: any) {
                setError(err.message || "Something went wrong");
            } finally {
                setLoading(false);
            }
        }

        fetchLogs();
    }, []);

    return (
        <div className="min-h-screen bg-gray-50">
            <Navbar />

            <div className="max-w-7xl mx-auto px-6 py-10">
                <h1 className="text-3xl font-semibold text-gray-800 mb-8">
                    Server Logs
                </h1>

                {loading && <p className="text-gray-600">Loading logs...</p>}
                {error && <p className="text-red-500">{error}</p>}

                {!loading && !error && (
                    <div className="bg-white shadow-sm rounded-xl border border-gray-200 overflow-auto max-h-[70vh]">
                        <ul className="p-4 font-mono text-xs text-gray-700 space-y-2">
                            {logs.length === 0 && <li>No logs found.</li>}
                            {logs.map((line, i) => (
                                <li key={i}>{line}</li>
                            ))}
                        </ul>
                    </div>
                )}
            </div>
        </div>
    );
}